H.background();
const Htop = P.h;
const g = 9.8, m = 1;
const frac = 0.5 + 0.5 * Math.cos(t * 1.2);
const h = Htop * frac;
const Etot = m * g * Htop;
const PE = m * g * h;
const KE = Etot - PE;
const speed = Math.sqrt(2 * g * Math.max(0, KE) / m);
const x0 = 80, y0 = 320, x1 = 320, y1 = 120;
H.line(x0, y0, x1, y1, { color: H.colors.grid, width: 3 });
H.line(x1, y1, x1, y0, { color: H.colors.grid, width: 1, dash: [4, 4] });
const bx = x0 + (x1 - x0) * frac;
const by = y0 + (y1 - y0) * frac;
H.circle(bx, by, 12, { fill: H.colors.accent2 });
H.text("h = " + h.toFixed(2) + " m", x1 + 10, y1, { color: H.colors.sub, size: 12 });
const bx0 = 480, bw = 70, base = 340, maxh = 220, scale = maxh / Etot;
H.rect(bx0, base - PE * scale, bw, PE * scale, { fill: H.colors.violet });
H.rect(bx0 + 100, base - KE * scale, bw, KE * scale, { fill: H.colors.warn });
H.rect(bx0 + 200, base - Etot * scale, bw, Etot * scale, { fill: H.colors.good });
H.line(bx0 - 10, base - Etot * scale, bx0 + 290, base - Etot * scale, { color: H.colors.good, width: 1, dash: [5, 5] });
H.text("PE", bx0 + 24, base + 16, { color: H.colors.sub, size: 12 });
H.text("KE", bx0 + 124, base + 16, { color: H.colors.sub, size: 12 });
H.text("E", bx0 + 230, base + 16, { color: H.colors.sub, size: 12 });
H.text("Conservation: KE + PE = constant", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("As the ball drops, PE converts to KE; total E stays fixed", 24, 52, { color: H.colors.sub, size: 13 });
H.text("PE = " + PE.toFixed(1) + " J   KE = " + KE.toFixed(1) + " J   v = " + speed.toFixed(1) + " m/s", 24, 78, { color: H.colors.sub, size: 13 });
H.text("E = " + Etot.toFixed(1) + " J (fixed)", 24, 96, { color: H.colors.good, size: 13 });
